/** Combines a main result with an optional additional result into a list.
  *
  * @param main
  *   The main result.
  * @param additional
  *   An optional additional result.
  * @return
  *   A list containing the main result and, if present, the additional
  *   result.
  */
private def combineResults(
    main: ResultEntity,
    additional: Option[ResultEntity],
): List[ResultEntity] =
  additional match {
    case Some(add) => List(main, add)
    case None      => List(main)
  }
